class TestAssembleStrainName:
    """
    These tests patch every external touchpoint:
        - requests.Session (context manager)
        - host_tools.scientific_to_vernacular
        - host_tools.match_species
        - location_tools.get_country_and_subdivision
        - package_config
    """

    def _patched(self, sm, fake_config, *, vernacular, subdivision, usage_id="3F72J"):
        """Return a contextmanager stack set up with the given return values."""
        cm = patch.multiple(
            sm.host_tools,
            scientific_to_vernacular=MagicMock(return_value=vernacular),
            match_species=MagicMock(return_value={"usage_id": usage_id}),
        )
        loc = patch.object(
            sm.location_tools, "get_country_and_subdivision",
            return_value=("US", subdivision),
        )
        cfg = patch.dict(sm.package_config, fake_config, clear=True)
        # requests.Session() used as a context manager -> return a dummy
        sess = patch.object(sm.requests, "Session", return_value=_DummySession())
        return cm, loc, cfg, sess

    def test_non_human_host_included(self, sm, fake_config):
        cm, loc, cfg, sess = self._patched(
            sm, fake_config, vernacular="Chicken", subdivision="US-VA"
        )
        with cm, loc, cfg, sess:
            name = sm.assemble_strain_name(
                virus_type="A",
                host="Gallus gallus",
                location="Richmond",
                country="US",
                sequence="02",
                year=2026,
                host_origin="d",
            )
        assert name == "A/chicken/US-VA/02-d.3F72J.1/2026"

    def _assemble(self, sm, fake_config, vernacular, **over):
        cm, loc, cfg, sess = self._patched(
            sm, fake_config, vernacular=vernacular, subdivision="US-VA"
        )
        kwargs = dict(
            virus_type="A",
            host="Meleagris gallopavo domesticus",
            location="Virginia",
            country="US",
            sequence="02",
            year=2026,
            host_origin="d",
        )
        kwargs.update(over)
        with cm, loc, cfg, sess:
            return sm.assemble_strain_name(**kwargs)

    def test_multi_word_host_spaces_become_underscores(self, sm, fake_config):
        name = self._assemble(sm, fake_config, "Domestic Turkey")
        assert name == "A/domestic_turkey/US-VA/02-d.3F72J.1/2026"

    def test_spaces_outside_host_segment_untouched(self, sm, fake_config):
        """Only the host segment is rewritten; other fields pass through."""
        name = self._assemble(sm, fake_config, "Domestic Turkey",
                              sequence="0 2")
        assert name == "A/domestic_turkey/US-VA/0 2-d.3F72J.1/2026"

    @pytest.mark.parametrize("vernacular", ["Odd_Bird", "Ducks/Geese"])
    def test_irreversible_vernacular_rejected(self, sm, fake_config, vernacular):
        with pytest.raises(ValueError, match="disallowed character"):
            self._assemble(sm, fake_config, vernacular)

    def test_assemble_keeps_its_name(self, sm):
        assert sm.assemble_strain_name.__name__ == "assemble_strain_name"
        assert sm.normalize_host.__name__ == "normalize_host"

    def test_subtype_appended_to_year(self, sm, fake_config):
        cm, loc, cfg, sess = self._patched(
            sm, fake_config, vernacular="Chicken", subdivision="US-VA"
        )
        with cm, loc, cfg, sess:
            name = sm.assemble_strain_name(
                virus_type="A",
                host="Gallus gallus",
                location="Richmond",
                country="US",
                sequence="02",
                year=2026,
                host_origin="d",
                subtype="H5N1",
            )
        assert name == "A/chicken/US-VA/02-d.3F72J.1/2026(H5N1)"

    def test_subtype_omitted_leaves_bare_year(self, sm, fake_config):
        """A name without a subtype must be unchanged by the new parameter."""
        cm, loc, cfg, sess = self._patched(
            sm, fake_config, vernacular="Chicken", subdivision="US-VA"
        )
        with cm, loc, cfg, sess:
            name = sm.assemble_strain_name(
                virus_type="B",
                host="Gallus gallus",
                location="Richmond",
                country="US",
                sequence="02",
                year=2026,
                host_origin="d",
                subtype=None,
            )
        assert name == "B/chicken/US-VA/02-d.3F72J.1/2026"

    def test_subtype_combines_with_isolate_suffix(self, sm, fake_config):
        cm, loc, cfg, sess = self._patched(
            sm, fake_config, vernacular="Chicken", subdivision="US-VA"
        )
        with cm, loc, cfg, sess:
            name = sm.assemble_strain_name(
                virus_type="A",
                host="Gallus gallus",
                location="Richmond",
                country="US",
                sequence="02",
                year=2026,
                isolate_version=2,
                lab_passage=True,
                subtype="H5N1",
            )
        assert name == "A/chicken/US-VA/02-3F72J.1-v2.L/2026(H5N1)"

    def test_bad_subtype_rejected_before_any_lookup(self, sm, fake_config):
        """The subtype is validated up front, so a bad one costs no API calls."""
        cm, loc, cfg, sess = self._patched(
            sm, fake_config, vernacular="Chicken", subdivision="US-VA"
        )
        with cm, loc, cfg, sess:
            with pytest.raises(ValueError, match="disallowed character"):
                sm.assemble_strain_name(
                    virus_type="A",
                    host="Gallus gallus",
                    location="Richmond",
                    country="US",
                    sequence="02",
                    year=2026,
                    subtype="H5/N1",
                )
            sm.host_tools.match_species.assert_not_called()

    def test_human_host_dropped(self, sm, fake_config):
        cm, loc, cfg, sess = self._patched(
            sm, fake_config, vernacular="Human", subdivision="US-NY"
        )
        with cm, loc, cfg, sess:
            name = sm.assemble_strain_name(
                virus_type="A",
                host="Human",
                location="New York",
                country="US",
                sequence="042",
                year=2026,
                subtype="H1N1",
            )
        # No host segment for human samples
        assert name == "A/US-NY/042-3F72J.1/2026(H1N1)"

    def test_collection_month_not_recorded(self, sm, fake_config):
        cm, loc, cfg, sess = self._patched(
            sm, fake_config, vernacular="Swine", subdivision="US-IA"
        )
        with cm, loc, cfg, sess:
            name = sm.assemble_strain_name(
                virus_type="A",
                host="Sus scrofa",
                location="Ames",
                country="US",
                sequence="9",
                year=2026,
                host_origin="d",
            )
        # Only the year survives into the name.
        assert name == "A/swine/US-IA/9-d.3F72J.1/2026"

    def test_optional_suffix_reaches_the_name(self, sm, fake_config):
        cm, loc, cfg, sess = self._patched(
            sm, fake_config, vernacular="Chicken", subdivision="US-VA"
        )
        with cm, loc, cfg, sess:
            name = sm.assemble_strain_name(
                virus_type="A",
                host="Gallus gallus",
                location="Richmond",
                country="US",
                sequence="02",
                year=2026,
                host_origin="d",
                isolate_version=2,
            )
        assert name == "A/chicken/US-VA/02-d.3F72J.1-v2/2026"

    def test_empty_subdivision_segment_dropped(self, sm, fake_config):
        # If the location tool yields an empty subdivision string, that
        # component is filtered out by the `if c` comprehension.
        cm, loc, cfg, sess = self._patched(
            sm, fake_config, vernacular="Chicken", subdivision=""
        )
        with cm, loc, cfg, sess:
            name = sm.assemble_strain_name(
                virus_type="A",
                host="Gallus gallus",
                location="Nowhere",
                country="US",
                sequence="1",
                year=2026,
                host_origin="d",
            )
        parts = name.split("/")
        assert "" not in parts
        assert parts[0] == "A"
        assert parts[1] == "chicken"

    def test_unresolvable_vernacular_raises(self, sm, fake_config):
        """A host with no vernacular name is an error, not a human sample."""
        cm, loc, cfg, sess = self._patched(
            sm, fake_config, vernacular=None, subdivision="US-VA"
        )
        with cm, loc, cfg, sess:
            with pytest.raises(ValueError, match="not a valid host name"):
                sm.assemble_strain_name(
                    virus_type="A",
                    host="Unknown",
                    location="Richmond",
                    country="US",
                    sequence="1",
                    year=2026,
                )

    def test_scientific_to_vernacular_called_with_session(self, sm, fake_config):
        s2v = MagicMock(return_value="Chicken")
        loc = patch.object(
            sm.location_tools, "get_country_and_subdivision",
            return_value=("US", "US-VA"),
        )
        cfg = patch.dict(sm.package_config, fake_config, clear=True)
        dummy = _DummySession()
        with patch.object(sm.host_tools, "scientific_to_vernacular", s2v), \
             patch.object(sm.host_tools, "match_species",
                          return_value={"usage_id": "X"}), \
             loc, cfg, \
             patch.object(sm.requests, "Session", return_value=dummy):
            sm.assemble_strain_name(
                virus_type="A",
                host="Gallus gallus",
                location="Richmond",
                country="US",
                sequence="1",
                year=2026,
                host_origin="d",
            )
        # host passed positionally, session passed as keyword
        args, kwargs = s2v.call_args
        assert args[0] == "Gallus gallus"
        assert kwargs["session"] is dummy


