class TestDecodeUli:
    @pytest.mark.parametrize("strain_id,uli,version,passage", [
        ("02-3F72J.1", None, None, False),
        ("02-3F72J.1-AB12C", "AB12C", None, False),
        ("02-3F72J.1-V1234", "V1234", None, False),   # uppercase V: a ULI
        ("02-3F72J.1-v1234", None, 1234, False),      # lowercase v: a version
        ("02-3F72J.1-L", None, None, True),
        ("02-3F72J.1-AB12C-v2.L", "AB12C", 2, True),
        ("02-3F72J.1-12345-L", "12345", None, True),
    ])
    def test_with_and_without_uli(self, sr, strain_id, uli, version, passage):
        with patch.object(sr, "resolve_scientific_name", return_value="Gallus gallus"):
            sid = sr.decode_strain_id(strain_id)
        assert (sid["uli"], sid["isolate_version"], sid["lab_passage"]) == \
            (uli, version, passage)
        assert sid["col_usage_id"] == "3F72J"

    @pytest.mark.parametrize("strain_id,uli", [
        ("02-3F72J.1-RG", None),            # 2 characters: never a ULI
        ("02-3F72J.1-AB12C-RG", "AB12C"),
        ("02-3F72J.1-AB12C-v2.L.RG", "AB12C"),
    ])
    def test_reverse_genetics(self, sr, strain_id, uli):
        with patch.object(sr, "resolve_scientific_name", return_value="Gallus gallus"):
            sid = sr.decode_strain_id(strain_id)
        assert sid["uli"] == uli
        assert sid["reverse_genetics"] is True

    @pytest.mark.parametrize("strain_id", [
        "02-3F72J.1-ab12c",          # lowercase ULI is not generated
        "02-3F72J.1-AB12-v2",        # 4-character ULI
        "02-3F72J.1-v2-AB12C",       # ULI after the suffix
        "02-3F72J.1-AB12C-AB12D",    # two ULIs
    ])
    def test_malformed(self, sr, strain_id):
        with patch.object(sr, "resolve_scientific_name", return_value="X y"), \
             pytest.raises(ValueError):
            sr.decode_strain_id(strain_id)

    def test_name_reports_uli(self, sr):
        with patch.object(sr, "resolve_scientific_name", return_value="Homo sapiens"):
            result = sr.decode_strain_name("A/US-CA/55-6MB3T.1-AB12C-v2/2020(H3N2)")
        assert (result["uli"], result["isolate_version"], result["subtype"]) == \
            ("AB12C", 2, "H3N2")

    def test_layout_in_error_message(self, sr):
        with pytest.raises(ValueError, match=r"\[-<uli>\]\[-<suffix>\]"):
            sr.decode_strain_id("02-3F72J.1-AB12C-v2-L")


