class TestHostMapIntegrity:
    """Guards on the curated data itself; a bad edit fails here, not in a name."""

    def test_species_keys_are_species_level(self, ht):
        for sci, entry in ht._load_host_map()["species"].items():
            assert len(sci.split()) >= 2, sci
            assert sci == ht.normalize_host(sci), sci
            assert entry["name"], sci

    def test_names_can_be_written_into_a_segment(self, ht):
        host_map = ht._load_host_map()
        names = [e["name"] for e in host_map["species"].values()]
        names += [g["name"] for g in host_map["groups"].values()]
        for name in names:
            assert not set(name) & set("_/"), name

    def test_group_label_is_its_segment(self, ht):
        for label, group in ht._load_host_map()["groups"].items():
            assert group["name"].lower() == label

    def test_no_group_name_shadows_a_species_name(self, ht):
        host_map = ht._load_host_map()
        species = {e["name"].lower() for e in host_map["species"].values()}
        assert not species & set(host_map["groups"])

    @pytest.mark.parametrize("field", ["heads", "members"])
    def test_heads_and_members_belong_to_one_group(self, ht, field):
        seen = {}
        for label, group in ht._load_host_map()["groups"].items():
            for item in group[field]:
                assert item not in seen, f"{item!r} in {seen.get(item)!r} and {label!r}"
                seen[item] = label

    def test_heads_are_lowercase(self, ht):
        for group in ht._load_host_map()["groups"].values():
            assert all(h == h.lower() for h in group["heads"])


class TestResolveHost:
    """Steps 1-3 must stay offline; the network helpers raise if touched."""

    @pytest.fixture
    def offline(self, ht):
        boom = MagicMock(side_effect=AssertionError("network step reached"))
        with patch.multiple(ht, match_species=boom, get_classification=boom,
                            gbif_vernacular_to_scientific=boom):
            yield

    def _species_name(self, ht, sci):
        return ht._load_host_map()["species"][sci]["name"]

    @pytest.mark.parametrize("text", [
        "Anas platyrhynchos", "anas platyrhynchos", "  Anas_platyrhynchos ",
    ])
    def test_scientific_species(self, ht, offline, text):
        r = ht.resolve_host(text, "DS")
        assert r == (self._species_name(ht, "Anas platyrhynchos"),
                     "Anas platyrhynchos", None, "species")

    def test_human(self, ht, offline):
        assert ht.resolve_host("Homo sapiens", "DS").label == "Human"
        assert ht.resolve_host("human", "DS").col_name == "Homo sapiens"

    def test_species_name_beats_head_noun(self, ht, offline):
        """"Cinnamon Teal" is curated, so it resolves to the species, not to duck."""
        r = ht.resolve_host("cinnamon teal", "DS")
        assert (r.label, r.matched_by) == ("Cinnamon Teal", "species")

    def test_common_species_name(self, ht, offline):
        name = self._species_name(ht, "Gallus gallus domesticus")
        r = ht.resolve_host(name.upper(), "DS")
        assert (r.col_name, r.matched_by) == ("Gallus gallus domesticus", "species")

    @pytest.mark.parametrize("text", ["duck", "Duck", "ducks", "unknown duck sp.", "Duck_"])
    def test_group_label(self, ht, offline, text):
        assert ht.resolve_host(text, "DS") == ("Duck", "Anatidae", None, "group")

    def test_member_taxon_keeps_its_own_name_for_the_id(self, ht, offline):
        assert ht.resolve_host("Anas", "DS") == ("Duck", "Anas", None, "member")
        assert ht.resolve_host("anatidae", "DS").label == "Waterfowl"

    @pytest.mark.parametrize("text,label", [
        ("baikal teal", "Duck"),
        ("Lesser Snow geese", "Goose"),
        ("Steller's sea lion", "Seal"),  # longest head wins over "lion"
        ("african lion", "Feline"),
        ("guinea fowl", "Gamebird"),     # over "fowl" -> avian
        ("unidentified yellow-legged gull sp.", "Gull"),
    ])
    def test_head_noun(self, ht, offline, caplog, text, label):
        r = ht.resolve_host(text, "DS")
        assert (r.label, r.matched_by, r.usage_id) == (label, "head_noun", None)
        assert "head noun" in caplog.text

    def test_col_walk_up_keeps_precise_id(self, ht):
        with patch.object(ht, "match_species", return_value={
                "usage_id": "ZZ1", "match_type": "exact",
                "scientific_name": "Anas zonorhyncha"}), \
             patch.object(ht, "get_classification",
                          return_value=["Anas", "Anatidae", "Aves"]):
            r = ht.resolve_host("Anas zonorhyncha", "DS")
        assert r == ("Duck", "Anas zonorhyncha", "ZZ1", "col")

    def test_col_match_outside_every_group_raises(self, ht):
        with patch.object(ht, "match_species", return_value={
                "usage_id": "ZZ2", "match_type": "exact",
                "scientific_name": "Apis mellifera"}), \
             patch.object(ht, "get_classification", return_value=["Apis", "Insecta"]):
            with pytest.raises(ValueError, match="no host group"):
                ht.resolve_host("Apis mellifera", "DS")

    def test_gbif_then_col(self, ht):
        def match(name, dataset_key, session=None):
            if name == "Melopsittacus undulatus":
                return {"usage_id": "BUD", "match_type": "exact",
                        "scientific_name": name}
            return None
        with patch.object(ht, "match_species", side_effect=match), \
             patch.object(ht, "get_classification",
                          return_value=["Melopsittacus", "Psittaciformes", "Aves"]), \
             patch.object(ht, "gbif_vernacular_to_scientific",
                          return_value="Melopsittacus undulatus"):
            r = ht.resolve_host("budgerigar", "DS")
        assert r == ("Avian", "Melopsittacus undulatus", "BUD", "gbif")

    def test_higherrank_col_match_is_not_used(self, ht):
        with patch.object(ht, "match_species", return_value={
                "usage_id": "3F72J", "match_type": "higherrank",
                "scientific_name": "Gallus gallus"}), \
             patch.object(ht, "gbif_vernacular_to_scientific", return_value=None):
            with pytest.raises(ValueError, match="host groups: .*duck"):
                ht.resolve_host("Gallus gallus bogus", "DS")

    def test_only_filler_words_raise(self, ht, offline):
        with pytest.raises(ValueError, match="names no host"):
            ht.resolve_host("unknown sp.", "DS")


class TestGbifVernacularToScientific:
    def _session(self, results):
        sess = MagicMock()
        sess.get.return_value.json.return_value = {"results": results}
        return sess

    @staticmethod
    def _rec(name, vernacular, rank="SPECIES", status="ACCEPTED"):
        return {"canonicalName": name, "rank": rank, "taxonomicStatus": status,
                "vernacularNames": [{"vernacularName": vernacular, "language": "eng"}]}

    def test_exact_accepted_species_only(self, ht):
        sess = self._session([
            self._rec("Larus a. smithsonianus", "Herring Gull", rank="SUBSPECIES"),
            self._rec(None, "Herring Gull x Glaucous Gull"),
            self._rec("Larus vegae", "Vega Gull"),
            self._rec("Larus argentatus", "herring gull"),
        ])
        assert ht.gbif_vernacular_to_scientific("Herring Gull", session=sess) == \
            "Larus argentatus"

    def test_two_species_with_the_name_is_ambiguous(self, ht):
        sess = self._session([self._rec("Larus argentatus", "Herring Gull"),
                              self._rec("Larus smithsonianus", "Herring Gull")])
        with pytest.raises(ValueError, match="ambiguous"):
            ht.gbif_vernacular_to_scientific("herring gull", session=sess)

    def test_no_exact_name(self, ht):
        sess = self._session([self._rec("Larus vegae", "Vega Gull")])
        assert ht.gbif_vernacular_to_scientific("herring gull", session=sess) is None


class TestHostResolverSwitch:
    """package.yaml host_resolver picks host_map or the legacy path."""

    def _assemble(self, sm, config, resolution, usage_id="9H6K5", host="duck",
                  host_origin="d"):
        match = MagicMock(return_value={"usage_id": usage_id})
        legacy = MagicMock(return_value="Should Not Be Used")
        with patch.multiple(sm.host_tools, resolve_host=MagicMock(return_value=resolution),
                            match_species=match, scientific_to_vernacular=legacy), \
             patch.object(sm.location_tools, "get_country_and_subdivision",
                          return_value=("US", "US-VA")), \
             patch.dict(sm.package_config, config, clear=True), \
             patch.object(sm.requests, "Session", return_value=_DummySession()):
            name = sm.assemble_strain_name(
                virus_type="A", host=host, location="Virginia", country="US",
                sequence="02", year=2026, host_origin=host_origin,
            )
        return name, match, legacy

    def test_group_mints_the_group_taxon_id(self, sm, fake_config, ht):
        config = {**fake_config, "host_resolver": "host_map"}
        res = ht.HostResolution("Duck", "Anatidae", None, "group")
        name, match, legacy = self._assemble(sm, config, res)
        assert name == "A/duck/US-VA/02-d.9H6K5.1/2026"
        assert match.call_args.args[0] == "Anatidae"
        legacy.assert_not_called()

    def test_known_usage_id_skips_the_col_lookup(self, sm, fake_config, ht):
        config = {**fake_config, "host_resolver": "host_map"}
        res = ht.HostResolution("Duck", "Anas zonorhyncha", "ZZ1", "col")
        name, match, _ = self._assemble(sm, config, res, host="Anas zonorhyncha")
        assert name == "A/duck/US-VA/02-d.ZZ1.1/2026"
        match.assert_not_called()

    def test_multi_word_label_uses_underscores(self, sm, fake_config, ht):
        config = {**fake_config, "host_resolver": "host_map"}
        res = ht.HostResolution("Domestic Turkey", "Meleagris gallopavo domesticus",
                                None, "species")
        name, _, _ = self._assemble(sm, config, res)
        assert name.split("/")[1] == "domestic_turkey"

    def test_human_drops_the_segment(self, sm, fake_config, ht):
        config = {**fake_config, "host_resolver": "host_map"}
        res = ht.HostResolution("Human", "Homo sapiens", None, "species")
        name, _, _ = self._assemble(sm, config, res, usage_id="6MB3T",
                                 host_origin=None)
        assert name == "A/US-VA/02-6MB3T.1/2026"

    @pytest.mark.parametrize("config_extra", [{}, {"host_resolver": "legacy"}])
    def test_legacy_is_the_default(self, sm, fake_config, config_extra):
        config = {**fake_config, **config_extra}
        with patch.multiple(sm.host_tools,
                            resolve_host=MagicMock(side_effect=AssertionError),
                            scientific_to_vernacular=MagicMock(return_value="Chicken"),
                            match_species=MagicMock(return_value={"usage_id": "3F72J"})), \
             patch.object(sm.location_tools, "get_country_and_subdivision",
                          return_value=("US", "US-VA")), \
             patch.dict(sm.package_config, config, clear=True), \
             patch.object(sm.requests, "Session", return_value=_DummySession()):
            name = sm.assemble_strain_name(
                virus_type="A", host="Gallus gallus domesticus", location="Virginia",
                country="US", sequence="02", year=2026, host_origin="d",
            )
        assert name == "A/chicken/US-VA/02-d.3F72J.1/2026"


